(() => {
  const MAP_SECTION='mapa', R=6371008.8;
  const state={map:null,areaLayer:null,resultLayers:{},areaGeoJSON:null,areaMeta:null,resultData:[]};
  function css(){if(document.getElementById('srMapStyles'))return;const e=document.createElement('style');e.id='srMapStyles';e.textContent='#srMap{height:520px;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:#eef3f5}.map-grid{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:12px;margin-top:12px}.map-tools{display:grid;gap:10px}.map-stat{display:grid;grid-template-columns:1fr 1fr;gap:8px}.map-drop{border:1px dashed var(--line);border-radius:12px;padding:12px;background:#f8fafb}.map-layer-row{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 0;border-bottom:1px solid var(--line)}.map-layer-row label{display:flex;align-items:center;gap:7px;font-size:12px}.map-layer-row input{width:auto}.map-note,.map-file{font-size:11px;color:var(--muted);line-height:1.45}.map-file{word-break:break-word}@media(max-width:900px){.map-grid{grid-template-columns:1fr}#srMap{height:420px}}';document.head.appendChild(e)}
  const safe=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
  const key=()=>`smartrisk.consultoria.map.${project()?.id||'draft'}`;
  const rad=x=>x*Math.PI/180;
  function hav(a,b){const dLat=rad(b[1]-a[1]),dLon=rad(b[0]-a[0]),la1=rad(a[1]),la2=rad(b[1]);const h=Math.sin(dLat/2)**2+Math.cos(la1)*Math.cos(la2)*Math.sin(dLon/2)**2;return 2*R*Math.asin(Math.min(1,Math.sqrt(h)))}
  function ringArea(c){if(!c||c.length<3)return 0;let s=0;for(let i=0;i<c.length;i++){const a=c[i],b=c[(i+1)%c.length];s+=rad(b[0]-a[0])*(2+Math.sin(rad(a[1]))+Math.sin(rad(b[1])))}return Math.abs(s*R*R/2)}
  function ringPer(c){if(!c||c.length<2)return 0;let d=0;for(let i=0;i<c.length-1;i++)d+=hav(c[i],c[i+1]);if(c.length>2&&(c[0][0]!==c.at(-1)[0]||c[0][1]!==c.at(-1)[1]))d+=hav(c.at(-1),c[0]);return d}
  function polygonMetrics(g){const r=g.coordinates||[];if(!r.length)return{area:0,perimeter:0};let area=ringArea(r[0]),perimeter=ringPer(r[0]);for(let i=1;i<r.length;i++){area-=ringArea(r[i]);perimeter+=ringPer(r[i])}return{area:Math.max(0,area),perimeter}}
  function metricsGeo(gj){let area=0,perimeter=0,points=0,lines=0,polygons=0;const walk=g=>{if(!g)return;if(g.type==='Polygon'){const m=polygonMetrics(g);area+=m.area;perimeter+=m.perimeter;polygons++}else if(g.type==='MultiPolygon')(g.coordinates||[]).forEach(c=>walk({type:'Polygon',coordinates:c}));else if(g.type==='Point')points++;else if(g.type==='MultiPoint')points+=(g.coordinates||[]).length;else if(g.type==='LineString'){lines++;perimeter+=ringPer(g.coordinates||[])}else if(g.type==='MultiLineString')(g.coordinates||[]).forEach(c=>{lines++;perimeter+=ringPer(c)});else if(g.type==='GeometryCollection')(g.geometries||[]).forEach(walk)};(gj.features||[]).forEach(f=>walk(f.geometry));return{areaHa:area/10000,perimeterKm:perimeter/1000,points,lines,polygons,features:(gj.features||[]).length}}
  function coords(n){return(n?.textContent||'').trim().split(/\s+/).map(x=>x.split(',').slice(0,2).map(Number)).filter(x=>Number.isFinite(x[0])&&Number.isFinite(x[1]))}
  function kmlToGeoJSON(text){const xml=new DOMParser().parseFromString(text,'application/xml');if(xml.querySelector('parsererror'))throw new Error('KML inválido.');const fs=[];for(const pm of [...xml.getElementsByTagName('Placemark')]){const name=pm.getElementsByTagName('name')[0]?.textContent?.trim()||'Elemento KML',description=pm.getElementsByTagName('description')[0]?.textContent?.trim()||'';for(const p of [...pm.getElementsByTagName('Point')]){const c=coords(p.getElementsByTagName('coordinates')[0]);if(c[0])fs.push({type:'Feature',properties:{name,description},geometry:{type:'Point',coordinates:c[0]}})}for(const l of [...pm.getElementsByTagName('LineString')]){const c=coords(l.getElementsByTagName('coordinates')[0]);if(c.length>1)fs.push({type:'Feature',properties:{name,description},geometry:{type:'LineString',coordinates:c}})}for(const p of [...pm.getElementsByTagName('Polygon')]){const out=p.getElementsByTagName('outerBoundaryIs')[0];if(!out)continue;const oc=coords(out.getElementsByTagName('coordinates')[0]);if(oc.length<3)continue;const rings=[oc];for(const inner of [...p.getElementsByTagName('innerBoundaryIs')]){const c=coords(inner.getElementsByTagName('coordinates')[0]);if(c.length>=3)rings.push(c)}fs.push({type:'Feature',properties:{name,description},geometry:{type:'Polygon',coordinates:rings}})}}if(!fs.length)throw new Error('El archivo no contiene geometrías KML compatibles.');return{type:'FeatureCollection',features:fs}}
  async function readSpatial(file){const ext=(file.name.split('.').pop()||'').toLowerCase();if(ext==='geojson'||ext==='json'){const j=JSON.parse(await file.text());return j.type==='FeatureCollection'?j:{type:'FeatureCollection',features:j.type==='Feature'?[j]:[]}}if(ext==='kml')return kmlToGeoJSON(await file.text());if(ext==='kmz'){if(!window.JSZip)throw new Error('No se pudo cargar el lector KMZ.');const zip=await JSZip.loadAsync(await file.arrayBuffer()),names=Object.keys(zip.files).filter(n=>/\.kml$/i.test(n));if(!names.length)throw new Error('El KMZ no contiene KML.');const n=names.find(x=>/(^|\/)doc\.kml$/i.test(x))||names[0];return kmlToGeoJSON(await zip.file(n).async('string'))}throw new Error('Usa KMZ, KML o GeoJSON.')}
  function persist(){try{localStorage.setItem(key(),JSON.stringify({area:state.areaGeoJSON,areaMeta:state.areaMeta,results:state.resultData}));return true}catch(_){return false}}
  function restore(){state.areaGeoJSON=null;state.areaMeta=null;state.resultData=[];try{const p=JSON.parse(localStorage.getItem(key())||'null');if(p){state.areaGeoJSON=p.area||null;state.areaMeta=p.areaMeta||null;state.resultData=Array.isArray(p.results)?p.results:[]}}catch(_){}}
  function popup(f){const d=document.createElement('div'),b=document.createElement('strong');b.textContent=f?.properties?.name||'Resultado';d.appendChild(b);if(f?.properties?.description){const p=document.createElement('div');p.textContent=f.properties.description;d.appendChild(p)}return d}
  function addLayer(gj,cat){const style=cat==='area'?{weight:3,fillOpacity:.08}:cat==='microzona'?{weight:2,fillOpacity:.22}:{radius:7,weight:2,fillOpacity:.75};return L.geoJSON(gj,{style:()=>style,pointToLayer:(_f,ll)=>L.circleMarker(ll,style),onEachFeature:(f,l)=>l.bindPopup(popup(f))})}
  function initMap(){if(!window.L)return;state.map?.remove();state.map=L.map('srMap').setView([-1.8312,-78.1834],6);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(state.map);state.resultLayers={};if(state.areaGeoJSON){state.areaLayer=addLayer(state.areaGeoJSON,'area').addTo(state.map);const b=state.areaLayer.getBounds();if(b.isValid())state.map.fitBounds(b,{padding:[25,25],maxZoom:17})}state.resultData.forEach((r,i)=>state.resultLayers[i]=addLayer(r.geojson,r.category).addTo(state.map))}
  const fmtHa=v=>Number.isFinite(v)?new Intl.NumberFormat('es-EC',{maximumFractionDigits:2}).format(v)+' ha':'—',fmtKm=v=>Number.isFinite(v)?new Intl.NumberFormat('es-EC',{maximumFractionDigits:2}).format(v)+' km':'—';
  function rows(){const a=state.areaGeoJSON?'<div class="map-layer-row"><label><input type="checkbox" data-map-toggle="area" checked> Área de estudio</label><span class="status ok">visible</span></div>':'';const r=state.resultData.map((x,i)=>`<div class="map-layer-row"><label><input type="checkbox" data-map-toggle="result" data-i="${i}" checked> ${safe(x.label)}</label><span class="badge">${safe(x.categoryLabel)}</span></div>`).join('');return a+r||'<div class="map-note">Todavía no hay capas cargadas.</div>'}
  function panelMap(p){const m=state.areaGeoJSON?metricsGeo(state.areaGeoJSON):null;return head('Mapa / Área de estudio',p.code+' · '+p.canton)+`<div class="map-grid"><div id="srMap"></div><aside class="map-tools"><div class="map-drop"><strong>1 · Cargar área de estudio</strong><div class="map-note">KMZ, KML o GeoJSON. Se calcula superficie y perímetro.</div><input id="areaSpatialFile" type="file" accept=".kmz,.kml,.geojson,.json" style="margin-top:8px;width:100%"><div class="map-file">${state.areaMeta?safe(state.areaMeta.name):'Sin archivo cargado'}</div></div><div class="map-stat"><div class="metric"><small>Área medida</small><strong>${m?fmtHa(m.areaHa):'—'}</strong></div><div class="metric"><small>Perímetro</small><strong>${m?fmtKm(m.perimeterKm):'—'}</strong></div></div><button class="btn primary" id="applyMapArea" ${m?'':'disabled'}>Usar superficie en proyecto</button><div class="map-drop"><strong>2 · Cargar resultados</strong><select id="resultCategory" style="width:100%;margin:6px 0"><option value="perforacion">Perforaciones / SPT</option><option value="geofisica">Vs / HVSR</option><option value="microzona">Microzonas / zonificación</option><option value="otro">Otra capa</option></select><input id="resultSpatialFile" type="file" accept=".kmz,.kml,.geojson,.json" style="width:100%"><div class="map-note" style="margin-top:6px">Solo se muestran coordenadas reales presentes en el archivo.</div></div><div class="box"><h3>Capas visibles</h3>${rows()}</div><div class="callout"><strong>Flujo</strong><div class="muted">PDOT/PUGS → polígono actualizado → área del proyecto → presupuesto → resultados sobre el mismo mapa.</div></div></aside></div>`}
  async function importArea(f){try{const gj=await readSpatial(f),m=metricsGeo(gj);if(!m.polygons)throw new Error('El área debe contener al menos un polígono.');state.areaGeoJSON=gj;state.areaMeta={name:f.name,loadedAt:new Date().toISOString(),areaHa:m.areaHa,perimeterKm:m.perimeterKm};persist();renderMain()}catch(e){alert(e.message||String(e))}}
  async function importResult(f,cat){try{const gj=await readSpatial(f),labels={perforacion:'Perforaciones / SPT',geofisica:'Vs / HVSR',microzona:'Microzonas',otro:'Otra capa'};state.resultData.push({label:f.name,category:cat,categoryLabel:labels[cat]||'Resultados',geojson:gj});persist();renderMain()}catch(e){alert(e.message||String(e))}}
  function bind(){document.getElementById('areaSpatialFile')?.addEventListener('change',e=>{const f=e.target.files?.[0];if(f)importArea(f)});document.getElementById('resultSpatialFile')?.addEventListener('change',e=>{const f=e.target.files?.[0];if(f)importResult(f,document.getElementById('resultCategory')?.value||'otro')});document.getElementById('applyMapArea')?.addEventListener('click',()=>{if(!state.areaGeoJSON)return;const m=metricsGeo(state.areaGeoJSON),p=project();p.areaPolygonHa=Number(m.areaHa.toFixed(2));p.areaPolygonPerimeterKm=Number(m.perimeterKm.toFixed(2));p.areaSource='Polígono georreferenciado';if(window.SmartRiskConsultoriaDraft){window.SmartRiskConsultoriaDraft.projectUrbanHa=p.areaPolygonHa;window.SmartRiskConsultoriaDraft._lastAutoUrban=null}persist();const b=document.getElementById('applyMapArea');b.textContent='✓ Superficie aplicada'});document.querySelectorAll('[data-map-toggle]').forEach(c=>c.onchange=()=>{if(c.dataset.mapToggle==='area'&&state.areaLayer){c.checked?state.areaLayer.addTo(state.map):state.map.removeLayer(state.areaLayer)}else{const l=state.resultLayers[Number(c.dataset.i)];if(l)c.checked?l.addTo(state.map):state.map.removeLayer(l)}})}
  const baseNav=renderNav,baseMain=renderMain;
  renderNav=function(){baseNav();const n=$('nav');if(!n||n.querySelector('[data-sec="mapa"]'))return;const b=document.createElement('button');b.className=`navbtn ${s.section===MAP_SECTION?'active':''}`;b.dataset.sec=MAP_SECTION;b.innerHTML='<span>⌖ Mapa / Área</span><span>›</span>';const d=n.querySelector('[data-sec="documentos"]');d?n.insertBefore(b,d):n.appendChild(b);b.onclick=()=>{s.section=MAP_SECTION;restore();renderNav();renderMain()}};
  renderMain=function(){if(s.section!==MAP_SECTION){baseMain();return}restore();$('main').innerHTML=panelMap(project());setTimeout(()=>{initMap();bind()},0)};
  css();renderNav();window.SmartRiskMapWorkspace={readSpatial,kmlToGeoJSON,metricsGeo,get state(){return state}};
})();